const CONTROLLER_PORT_ENV = ['OPENCODE_WEB_PORT', 'OPENCODE_CONTROL_PORT', 'PROJECT_FILE_PORT']
const LOOPBACK_HOSTS = new Set(['localhost', '127.0.0.1', '[::1]'])
