#telemetryState { color: var(--green); }
body.pulling #telemetryState { color: var(--red); animation: pulse 1s infinite; }
.gauge-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 4px 8px; margin: 8px 0 10px; }
.gauge { position: relative; display: flex; flex-direction: column; align-items: center; padding: 2px 0 0; }
.gauge svg { width: 76px; height: 76px; transform: rotate(135deg); overflow: visible; }
.gauge .g-track { fill: none; stroke: rgba(255, 255, 255, .075); stroke-width: 4; stroke-dasharray: 136 200; stroke-linecap: round; }
.gauge .g-fill {
  fill: none;
  stroke: var(--accent);
  stroke-width: 4;
  stroke-linecap: round;
  stroke-dasharray: 0 200;
  filter: drop-shadow(0 0 4px rgba(67, 232, 208, .5));
  transition: stroke-dasharray .12s linear, stroke .2s;
}
.gauge[data-gauge="boost"] .g-fill { stroke: var(--blue); filter: drop-shadow(0 0 4px rgba(97, 184, 255, .5)); }
.gauge[data-gauge="egt"] .g-fill { stroke: var(--orange); filter: drop-shadow(0 0 4px rgba(255, 138, 61, .5)); }
.gauge[data-gauge="afr"] .g-fill { stroke: var(--green); filter: drop-shadow(0 0 4px rgba(98, 208, 164, .5)); }
.gauge.is-alert .g-fill { stroke: var(--red) !important; filter: drop-shadow(0 0 7px rgba(255, 77, 94, .9)); }
.g-read { position: absolute; top: 25px; left: 0; right: 0; display: flex; flex-direction: column; align-items: center; line-height: 1; pointer-events: none; }
.g-read b { font-family: var(--font-display); font-size: 15px; font-weight: 700; letter-spacing: -.02em; }
.g-read span { margin-top: 3px; font-size: 7px; letter-spacing: .16em; color: var(--dim); font-weight: 700; }
.gauge > small { margin-top: 0; font-size: 7px; letter-spacing: .2em; color: var(--dim); font-weight: 700; }

.margin-row, .health-row { margin-top: 8px; }
.margin-label, .health-label {
  display: flex; justify-content: space-between;
  font-size: 8px; letter-spacing: .15em; color: var(--dim); font-weight: 700;
}
.margin-label b, .health-label b { color: var(--text); letter-spacing: .03em; }
.margin-bar, .health-bar { height: 4px; border-radius: 4px; background: rgba(255, 255, 255, .08); margin-top: 5px; overflow: hidden; }
.margin-bar span { display: block; height: 100%; width: 50%; background: var(--green); border-radius: 4px; transition: width .25s, background .25s; box-shadow: 0 0 8px currentColor; }
.health-bar span { display: block; height: 100%; width: 100%; background: var(--accent); border-radius: 4px; transition: width .35s, background .3s; }
.knock-alert {
  margin-top: 9px;
  border: 1px solid rgba(255, 77, 94, .2);
  background: rgba(255, 77, 94, .04);
  border-radius: 6px;
  padding: 6px 8px;
  text-align: center;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: .18em;
  color: var(--dim);
  transition: .2s;
}
.knock-alert span { color: var(--red); float: right; }
.knock-alert.is-live { background: rgba(255, 77, 94, .15); border-color: rgba(255, 77, 94, .55); color: var(--red); animation: knockFlash .25s infinite alternate; }

/* ============================== center ============================== */
#cameraBar {
  position: absolute;
  top: 4px; left: 50%;
  transform: translateX(-50%);
  z-index: 4;
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 4px;
  border: 1px solid rgba(160, 190, 205, .12);
  border-radius: 8px;
  background: rgba(6, 9, 12, .58);
  backdrop-filter: blur(12px);
}
.cam-btn {
  border: 0; background: transparent; color: var(--muted);
  font-size: 9px; font-weight: 700; letter-spacing: .16em;
  padding: 6px 11px; border-radius: 5px; transition: .16s;
}
.cam-btn:hover { color: var(--text); }
.cam-btn.is-active { color: var(--text); background: rgba(255, 255, 255, .09); }
.cam-hint { padding: 0 8px 0 5px; font-size: 8px; color: var(--dim); letter-spacing: .13em; font-weight: 600; }

#toast {
  position: absolute;
  left: 50%;
  bottom: 274px;
  transform: translate(-50%, 12px);
  z-index: 12;
  padding: 9px 16px;
  border-radius: 7px;
  border: 1px solid rgba(67, 232, 208, .22);
  background: rgba(6, 12, 14, .92);
  color: var(--text);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: .06em;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: .3s;
  box-shadow: 0 8px 30px rgba(0, 0, 0, .4);
}
#toast.show { opacity: 1; transform: translate(-50%, 0); }
#toast.bad { border-color: rgba(255, 77, 94, .4); color: #ffbcc2; }
#toast.gold { border-color: rgba(255, 209, 102, .4); color: var(--gold); }

/* chart */
.chart-panel {
  position: absolute;
  left: 50%;
  bottom: 0;
  transform: translateX(-50%);
  width: min(570px, 100%);
  padding: 12px 14px 9px;
}
.chart-head { display: flex; align-items: center; justify-content: space-between; }
#chartMode { color: var(--accent); border: 1px solid rgba(67, 232, 208, .22); padding: 2px 5px; border-radius: 3px; letter-spacing: .13em; }
body.pulling #chartMode { color: var(--red); border-color: rgba(255, 77, 94, .35); animation: pulse .7s infinite; }
.chart-legend { display: flex; align-items: center; gap: 11px; font-size: 7.5px; font-weight: 700; letter-spacing: .13em; color: var(--dim); }
.chart-legend span { display: flex; align-items: center; gap: 4px; }
.chart-legend i { width: 11px; height: 2px; border-radius: 2px; display: block; }
.leg-hp i { background: var(--orange); box-shadow: 0 0 5px var(--orange); }
.leg-tq i { background: var(--blue); box-shadow: 0 0 5px var(--blue); }
.leg-ghost i { background: repeating-linear-gradient(90deg, var(--dim) 0 3px, transparent 3px 5px); }
#chart { display: block; width: 100%; height: 154px; margin-top: 7px; }
.chart-foot {
  display: flex; gap: 12px; align-items: center;
  border-top: 1px solid rgba(255, 255, 255, .07);
  padding-top: 7px; margin-top: 2px;
  font-size: 8px; letter-spacing: .09em; font-weight: 700; color: var(--dim);
  white-space: nowrap;
}
.chart-foot span:last-child { margin-left: auto; }
.chart-foot .ok { color: var(--green); }
.chart-foot .warn { color: var(--gold); }
.chart-foot .bad { color: var(--red); }

/* ============================== console ============================== */
#rightRail { min-height: 0; }
.console { height: 100%; display: flex; flex-direction: column; overflow: hidden; }
.console-head {
  display: flex; align-items: flex-end; justify-content: space-between;
  padding: 14px 16px 11px;
  border-bottom: 1px solid rgba(255, 255, 255, .07);
  flex: none;
}
.console-head h2 { margin: 5px 0 0; font-family: var(--font-display); font-size: 15px; letter-spacing: .09em; font-weight: 700; }
.console-tabs { display: flex; gap: 3px; padding: 3px; border-radius: 6px; background: rgba(255, 255, 255, .04); }
.console-tab {
  border: 0; background: transparent; color: var(--dim);
  font-size: 9px; font-weight: 700; letter-spacing: .15em;
  padding: 5px 9px; border-radius: 4px;
}
.console-tab.is-active { background: rgba(67, 232, 208, .14); color: var(--accent); }
.console-view { padding: 11px 14px 13px; overflow-y: auto; overflow-x: hidden; flex: 1; min-height: 0; scrollbar-width: thin; scrollbar-color: rgba(255,255,255,.14) transparent; }
.console-view::-webkit-scrollbar { width: 5px; }
.console-view::-webkit-scrollbar-thumb { background: rgba(255, 255, 255, .14); border-radius: 3px; }

.spec-strip {
  display: grid; grid-template-columns: 1.25fr .8fr .7fr; gap: 6px;
  padding: 8px 9px; margin-bottom: 11px;
  border: 1px solid rgba(255, 255, 255, .055);
  border-radius: 7px; background: rgba(255, 255, 255, .022);
}
.spec-strip div { min-width: 0; }
.spec-strip span { display: block; font-size: 7px; letter-spacing: .17em; color: var(--dim); font-weight: 700; }
.spec-strip b { display: block; margin-top: 3px; font-size: 10px; font-weight: 700; letter-spacing: .05em; color: var(--text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
#specHealth { color: var(--green); }

.sliders { display: flex; flex-direction: column; gap: 10px; }
.slider-row.is-disabled { opacity: .45; }
.slider-top { display: flex; align-items: baseline; justify-content: space-between; }
.slider-top label { font-size: 9px; letter-spacing: .16em; color: var(--muted); font-weight: 700; }
.slider-val { display: flex; align-items: baseline; gap: 3px; }
.slider-val b { font-family: var(--font-display); font-size: 14px; font-weight: 700; letter-spacing: -.02em; }
.slider-val span { font-size: 8px; color: var(--dim); font-weight: 700; letter-spacing: .05em; }
.slider-scale { display: flex; justify-content: space-between; margin-top: 3px; font-size: 7px; letter-spacing: .1em; color: var(--dim); font-weight: 600; }

input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  display: block;
  width: 100%;
  height: 17px;
  margin: 2px 0 0;
  padding: 0;
  background: transparent;
  cursor: pointer;
  touch-action: pan-y;
}
input[type="range"]::-webkit-slider-runnable-track {
  height: 4px;
  border-radius: 3px;
  background: linear-gradient(90deg, var(--accent) 0 var(--pct, 50%), rgba(255, 255, 255, .09) var(--pct, 50%) 100%);
  box-shadow: 0 0 7px rgba(67, 232, 208, .12);
}
input[type="range"]::-moz-range-track { height: 4px; border-radius: 3px; background: rgba(255, 255, 255, .09); }
input[type="range"]::-moz-range-progress { height: 4px; border-radius: 3px; background: var(--accent); }
input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 13px; height: 13px;
  margin-top: -4.5px;
  border-radius: 50%;
  background: #eafbf8;
  border: 2px solid #0a1214;
  box-shadow: 0 0 0 1px var(--accent), 0 0 12px rgba(67, 232, 208, .55);
}
input[type="range"]::-moz-range-thumb {
  width: 11px; height: 11px; border-radius: 50%;
  background: #eafbf8; border: 2px solid #0a1214;
  box-shadow: 0 0 0 1px var(--accent), 0 0 12px rgba(67, 232, 208, .55);
}
.slider-row[data-key="timing"] input[type="range"]::-webkit-slider-runnable-track {
  background: linear-gradient(90deg, #9adfd5 0 var(--pct, 50%), rgba(255,255,255,.09) var(--pct, 50%) 100%);
}
.slider-row[data-key="afr"] input[type="range"]::-webkit-slider-runnable-track {
  background: linear-gradient(90deg, #62d0a4 0 var(--pct, 50%), #ff8a3d var(--pct, 50%) 100%);
}
.slider-row[data-key="rev"] input[type="range"]::-webkit-slider-runnable-track {
  background: linear-gradient(90deg, var(--accent) 0 var(--pct, 50%), rgba(255, 255, 255, .09) var(--pct, 50%) 100%);
}
.slider-row[data-key="rev"].over-safe input[type="range"]::-webkit-slider-runnable-track {
  background: linear-gradient(90deg, var(--accent) 0 var(--safe-pct, 50%), var(--red) var(--safe-pct, 50%) 100%);
}

.fuel-block {
  display: flex; align-items: center; gap: 8px;
  margin-top: 11px;
  padding-top: 10px;
  border-top: 1px solid rgba(255, 255, 255, .06);
}
.fuel-label { font-size: 8px; letter-spacing: .17em; color: var(--dim); font-weight: 700; }
.fuel-chips { display: flex; gap: 3px; }
.fuel-chip {
  border: 1px solid rgba(255, 255, 255, .09);
  background: rgba(255, 255, 255, .025);
  color: var(--muted);
  border-radius: 4px;
  font-size: 9px; font-weight: 700; letter-spacing: .04em;
  padding: 3px 6px;
  transition: .16s;
}
.fuel-chip:hover { color: var(--text); }
.fuel-chip.is-active { color: #05201d; background: var(--accent); border-color: var(--accent); }
.fuel-chip[data-fuel="e85"].is-active { background: var(--orange); border-color: var(--orange); color: #1b0d04; }
.fuel-cost { margin-left: auto; font-size: 8px; color: var(--dim); font-weight: 600; white-space: nowrap; }

.prediction {
  margin-top: 10px;
  padding: 9px 10px;
  border: 1px solid rgba(255, 255, 255, .07);
  border-radius: 8px;
  background: linear-gradient(135deg, rgba(67, 232, 208, .055), rgba(255, 255, 255, .015));
}
.pred-main { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.pred-main div { display: flex; align-items: baseline; flex-wrap: wrap; gap: 4px; }
.pred-main span { flex-basis: 100%; font-size: 7px; letter-spacing: .15em; color: var(--dim); font-weight: 700; }
.pred-main b { font-family: var(--font-display); font-size: 21px; line-height: 1; font-weight: 700; color: var(--text); }
.pred-main em { font-style: normal; font-size: 8px; color: var(--accent); font-weight: 700; letter-spacing: .07em; }
.pred-flags { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 8px; }
.flag {
  font-size: 7.5px; font-weight: 700; letter-spacing: .08em;
  padding: 2px 5px; border-radius: 3px;
  color: var(--muted); background: rgba(255, 255, 255, .05);
  border: 1px solid transparent;
}
.flag.ok { color: var(--green); background: rgba(98, 208, 164, .08); border-color: rgba(98, 208, 164, .2); }
.flag.warn { color: var(--gold); background: rgba(255, 209, 102, .08); border-color: rgba(255, 209, 102, .22); }
.flag.bad { color: var(--red); background: rgba(255, 77, 94, .1); border-color: rgba(255, 77, 94, .28); }
.pred-warning { display: none; margin-top: 6px; font-size: 9px; line-height: 1.25; color: var(--gold); letter-spacing: .02em; }
.pred-warning.show { display: block; }

.run-btn {
  position: relative;
  width: 100%;
  margin-top: 11px;
  border: 0;
  border-radius: 8px;
  padding: 12px 14px 10px;
  text-align: left;
  color: #05201d;
  background: linear-gradient(100deg, #43e8d0 0%, #9df7e9 55%, #43e8d0 100%);
  background-size: 200% 100%;
  box-shadow: 0 0 0 1px rgba(67, 232, 208, .25), 0 10px 30px rgba(67, 232, 208, .16);
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 12px 100%, 0 calc(100% - 12px));
  transition: transform .15s, box-shadow .2s, filter .2s;
  overflow: hidden;
}
.run-btn::after {
  content: '';
  position: absolute;
  top: 0; bottom: 0; left: -40%;
  width: 25%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, .55), transparent);
  transform: skewX(-20deg);
  animation: sheen 4.5s infinite;
}
.run-btn:hover { filter: brightness(1.06); box-shadow: 0 0 0 1px rgba(67, 232, 208, .45), 0 12px 40px rgba(67, 232, 208, .28); }
.run-btn:active { transform: translateY(1px); }
.run-btn .run-main { display: block; font-family: var(--font-display); font-size: 14px; font-weight: 800; letter-spacing: .11em; }
.run-btn .run-sub { display: block; margin-top: 4px; font-size: 8px; font-weight: 700; letter-spacing: .1em; opacity: .62; }
.run-btn .run-sub b { font-weight: 800; }
.run-btn kbd { font-family: var(--font-body); font-weight: 700; background: rgba(0, 0, 0, .15); border-radius: 3px; padding: 1px 4px; }
.run-btn.is-live { background: linear-gradient(100deg, #ff4d5e, #ff8a7a); color: #250508; animation: livePulse 1.2s infinite; }
.run-btn.is-live::after { display: none; }

.tune-hint { display: flex; gap: 8px; margin-top: 10px; padding: 8px 9px; border-radius: 7px; background: rgba(255, 255, 255, .026); border-left: 2px solid rgba(67, 232, 208, .4); }
.hint-icon {
  flex: none; width: 15px; height: 15px; border-radius: 50%;
  border: 1px solid rgba(67, 232, 208, .4);
  color: var(--accent); display: grid; place-items: center;
  font-family: var(--font-display); font-size: 8px; font-weight: 700;
}
.tune-hint p { margin: 0; color: var(--muted); font-size: 9.5px; line-height: 1.35; letter-spacing: .02em; }

/* shop */
.shop-top { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; }
.shop-cash-label { display: block; font-size: 7px; letter-spacing: .17em; color: var(--dim); font-weight: 700; }
#shopCash { font-family: var(--font-display); font-size: 19px; color: var(--gold); }
.health-chip { font-size: 8px; font-weight: 700; letter-spacing: .12em; padding: 5px 8px; border-radius: 4px; background: rgba(98, 208, 164, .09); border: 1px solid rgba(98, 208, 164, .2); color: var(--green); }
.health-chip.bad { color: var(--red); border-color: rgba(255, 77, 94, .3); background: rgba(255, 77, 94, .08); }
.shop-list { display: flex; flex-direction: column; gap: 7px; }
.upgrade-card { padding: 8px 9px; border-radius: 7px; border: 1px solid rgba(255, 255, 255, .065); background: rgba(255, 255, 255, .024); }
.upgrade-top { display: flex; align-items: center; gap: 6px; }
.upgrade-top h4 { margin: 0; font-size: 9px; font-weight: 700; letter-spacing: .12em; color: var(--muted); }
.pips { display: flex; gap: 2px; margin-left: 2px; }
.pips i { width: 9px; height: 3px; border-radius: 2px; background: rgba(255, 255, 255, .13); }
.pips i.on { background: var(--accent); box-shadow: 0 0 5px rgba(67, 232, 208, .5); }
.upgrade-name { margin-left: auto; font-size: 9px; font-weight: 700; color: var(--text); }
.upgrade-mid { display: flex; align-items: flex-end; justify-content: space-between; gap: 8px; margin-top: 4px; }
.upgrade-desc { font-size: 8.5px; line-height: 1.25; color: var(--dim); max-width: 66%; }
.upgrade-delta { font-size: 7.5px; color: var(--green); font-weight: 700; letter-spacing: .03em; text-align: right; white-space: nowrap; }
.buy-btn {
  flex: none;
  border: 1px solid rgba(67, 232, 208, .28);
  background: rgba(67, 232, 208, .08);
  color: var(--accent);
  border-radius: 5px;
  padding: 5px 8px;
  font-size: 8px; font-weight: 800; letter-spacing: .08em;
  transition: .16s;
}
.buy-btn:hover:not(:disabled) { background: rgba(67, 232, 208, .18); }
.buy-btn:disabled { opacity: .38; cursor: not-allowed; }
.buy-btn.maxed { color: var(--dim); border-color: rgba(255, 255, 255, .1); background: transparent; }
.repair-btn {
  width: 100%; margin-top: 10px;
  border: 1px solid rgba(255, 209, 102, .26);
  background: rgba(255, 209, 102, .07);
  color: var(--gold);
  border-radius: 7px; padding: 9px;
  font-size: 9px; font-weight: 800; letter-spacing: .13em;
  transition: .16s;
}
.repair-btn:hover:not(:disabled) { background: rgba(255, 209, 102, .14); }
.repair-btn:disabled { opacity: .35; cursor: not-allowed; }
.repair-btn span { float: right; }
.shop-note { margin: 8px 0 0; color: var(--dim); font-size: 8.5px; line-height: 1.35; }

/* ============================== pull hud ============================== */
#pullHud {
  position: absolute;
  left: 50%;
  bottom: 246px;
  z-index: 20;
  width: min(610px, calc(100% - 40px));
  transform: translate(-50%, 14px);
  opacity: 0;
  pointer-events: none;
  padding: 11px 16px 10px;
  border-radius: 11px;
  border: 1px solid rgba(255, 138, 61, .22);
  background: linear-gradient(180deg, rgba(17, 12, 9, .9), rgba(7, 8, 10, .93));
  box-shadow: 0 20px 50px rgba(0, 0, 0, .55), inset 0 1px 0 rgba(255, 255, 255, .04);
  backdrop-filter: blur(14px);
  transition: opacity .25s, transform .25s;
}
body.pulling #pullHud { opacity: 1; transform: translate(-50%, 0); pointer-events: auto; }
body.pulling #chartPanel { box-shadow: 0 0 0 1px rgba(255, 138, 61, .13), 0 22px 48px rgba(0, 0, 0, .4); }
.pull-status { font-size: 8px; font-weight: 700; letter-spacing: .2em; color: var(--orange); display: flex; align-items: center; gap: 6px; }
.rec-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--red); box-shadow: 0 0 9px var(--red); animation: pulse .8s infinite; }
.pull-big { display: grid; grid-template-columns: 1fr 1.1fr 1fr; align-items: end; gap: 24px; margin: 5px 0 3px; }
.pull-num, .pull-rpm { display: flex; flex-direction: column; align-items: center; line-height: 1; }
.pull-num b { font-family: var(--font-display); font-size: 31px; font-weight: 800; letter-spacing: -.03em; color: var(--text); text-shadow: 0 0 18px rgba(255, 255, 255, .12); }
.pull-rpm b { font-family: var(--font-display); font-size: 40px; font-weight: 800; letter-spacing: -.04em; color: var(--orange); text-shadow: 0 0 24px rgba(255, 138, 61, .35); }
.pull-num span, .pull-rpm span { margin-top: 4px; font-size: 7px; letter-spacing: .2em; color: var(--dim); font-weight: 700; }
.pull-sub { display: flex; justify-content: center; gap: 18px; font-size: 8px; letter-spacing: .12em; color: var(--muted); font-weight: 700; border-top: 1px solid rgba(255, 255, 255, .07); padding-top: 7px; }
.abort-btn {
  position: absolute; top: 9px; right: 12px;
  border: 1px solid rgba(255, 77, 94, .25);
  background: rgba(255, 77, 94, .08);
  color: #ff9aa4;
  border-radius: 4px; padding: 3px 6px;
  font-size: 7px; font-weight: 800; letter-spacing: .1em;
}
.abort-btn:hover { background: rgba(255, 77, 94, .16); }
#pullHud.knock { border-color: rgba(255, 77, 94, .65); box-shadow: 0 0 40px rgba(255, 60, 80, .28), 0 20px 50px rgba(0, 0, 0, .55); }

/* ============================== mobile telemetry ============================== */
#mobileTelemetry { display: none; }

/* ============================== title screen ============================== */
.screen { position: absolute; inset: 0; z-index: 60; }
#titleScreen {
  display: flex;
  align-items: center;
  background:
    radial-gradient(ellipse at 66% 42%, rgba(7, 12, 16, 0.05) 0%, rgba(4, 7, 10, 0.52) 43%, rgba(3, 5, 7, 0.94) 100%),
    linear-gradient(90deg, rgba(3, 5, 8, 0.93) 0%, rgba(3, 5, 8, 0.55) 38%, rgba(3, 5, 8, 0.02) 64%, rgba(3, 5, 8, 0.4) 100%);
  transition: opacity .65s ease, visibility .65s;
}
#titleScreen.is-gone { opacity: 0; visibility: hidden; pointer-events: none; }
.title-glow {
  position: absolute; left: -12%; top: 50%; width: 60vw; height: 70vh;
  transform: translateY(-50%);
  background: radial-gradient(ellipse, rgba(67, 232, 208, .1) 0%, transparent 65%);
  pointer-events: none;
}
.title-inner { position: relative; padding: 42px 0 36px 7vw; width: min(690px, 82vw); }
.title-eyebrow {
  display: flex; align-items: center; gap: 10px;
  font-size: 9px; font-weight: 700; letter-spacing: .32em; color: var(--accent);
  text-transform: uppercase;
}
.title-eyebrow span { display: block; width: 28px; height: 1px; background: var(--accent); opacity: .5; }
.title-inner h1 {
  margin: 24px 0 16px;
  font-family: var(--font-display);
  font-size: clamp(62px, 10.6vw, 142px);
  font-weight: 800;
  line-height: .82;
  letter-spacing: .015em;
  text-shadow: 0 0 60px rgba(67, 232, 208, .12);
}
.title-inner h1 span {
  color: var(--accent);
  text-shadow: 0 0 55px rgba(67, 232, 208, .32);
}
.title-tagline {
  margin: 0;
  font-size: clamp(13px, 1.35vw, 17px);
  font-weight: 700;
  letter-spacing: .17em;
  color: var(--text);
}
.title-tagline em { font-style: normal; color: var(--orange); }
.title-copy {
  margin: 18px 0 0;
  max-width: 480px;
  color: #9baebb;
  font-size: 14px;
  line-height: 1.5;
  letter-spacing: .015em;
}
.title-chips { display: flex; flex-wrap: wrap; gap: 9px; margin-top: 22px; }
.title-chips span {
  display: flex; align-items: center; gap: 6px;
  border: 1px solid rgba(163, 196, 214, .15);
  background: rgba(12, 18, 23, .6);
  border-radius: 4px;
  padding: 5px 9px;
  color: var(--muted);
  font-size: 8px; font-weight: 700; letter-spacing: .16em;
  backdrop-filter: blur(6px);
}
.title-chips i { width: 4px; height: 4px; border-radius: 50%; background: var(--accent); box-shadow: 0 0 6px var(--accent); }
.start-btn {
  position: relative;
  margin-top: 34px;
  border: 0;
  min-width: 230px;
  padding: 16px 30px;
  color: #04201c;
  background: linear-gradient(105deg, #43e8d0 0%, #b2fff3 50%, #43e8d0 100%);
  background-size: 220% 100%;
  font-family: var(--font-display);
  font-size: 15px;
  font-weight: 800;
  letter-spacing: .16em;
  border-radius: 3px;
  clip-path: polygon(0 0, calc(100% - 16px) 0, 100% 16px, 100% 100%, 16px 100%, 0 calc(100% - 16px));
  box-shadow: 0 0 40px rgba(67, 232, 208, .20);
  transition: transform .18s, box-shadow .2s, background-position .5s;
  animation: startPulse 3.4s infinite;
}
.start-btn:hover { transform: translateY(-2px); background-position: 100% 0; box-shadow: 0 0 60px rgba(67, 232, 208, .36); }
.start-btn:active { transform: translateY(0); }
.title-foot {
  display: flex; gap: 20px; margin-top: 34px;
  color: var(--dim); font-size: 8px; font-weight: 700; letter-spacing: .2em;
}
.title-foot span { display: flex; align-items: center; gap: 6px; }
.title-foot span::before { content: ''; width: 3px; height: 3px; background: var(--dim); border-radius: 50%; }
.title-corner { position: absolute; width: 26px; height: 26px; border-color: rgba(67, 232, 208, .35); border-style: solid; pointer-events: none; }
.title-corner.tl { top: 20px; left: 20px; border-width: 1px 0 0 1px; }
.title-corner.tr { top: 20px; right: 20px; border-width: 1px 1px 0 0; }
.title-corner.bl { bottom: 20px; left: 20px; border-width: 0 0 1px 1px; }
.title-corner.br { bottom: 20px; right: 20px; border-width: 0 1px 1px 0; }
.title-version { position: absolute; right: 26px; bottom: 26px; font-size: 8px; letter-spacing: .2em; color: var(--dim); font-weight: 700; }

/* ============================== modals ============================== */
#modalRoot { position: absolute; inset: 0; z-index: 80; }
.modal-backdrop {
  position: absolute; inset: 0;
  display: flex; align-items: center; justify-content: center;
  padding: 24px;
  background: rgba(2, 5, 8, .72);
  backdrop-filter: blur(9px) saturate(.8);
  animation: fadeIn .2s ease;
}
.modal {
  position: relative;
  width: min(1040px, 94vw);
  max-height: min(850px, 90dvh);
  overflow-y: auto;
  border: 1px solid var(--line-strong);
  border-radius: 16px;
  background:
    linear-gradient(180deg, rgba(16, 23, 30, .98), rgba(6, 9, 12, .985));
  box-shadow: 0 40px 100px rgba(0, 0, 0, .65), inset 0 1px 0 rgba(255, 255, 255, .06);
  padding: 24px 26px 24px;
  scrollbar-width: thin;
  scrollbar-color: rgba(255,255,255,.16) transparent;
  animation: modalIn .3s cubic-bezier(.2,.8,.2,1);
}
.modal::-webkit-scrollbar { width: 6px; }
.modal::-webkit-scrollbar-thumb { background: rgba(255,255,255,.16); border-radius: 4px; }
.modal-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px; margin-bottom: 18px; }
.modal-kicker { font-size: 9px; letter-spacing: .26em; color: var(--accent); font-weight: 700; }
.modal-head h2 { margin: 7px 0 0; font-family: var(--font-display); font-size: clamp(24px, 3vw, 38px); line-height: 1; letter-spacing: .02em; font-weight: 800; }
.modal-head p { margin: 8px 0 0; color: var(--muted); font-size: 12px; max-width: 620px; }
.modal-close {
  flex: none;
  width: 36px; height: 36px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: rgba(255, 255, 255, .03);
  color: var(--muted);
  font-size: 18px; line-height: 1;
}
.modal-close:hover { color: var(--text); background: rgba(255, 255, 255, .07); }

/* contracts */
.contract-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 11px; }
.job-card {
  position: relative;
  display: flex; flex-direction: column;
  padding: 14px 14px 12px;
  border-radius: 10px;
  border: 1px solid rgba(255, 255, 255, .08);
  background: rgba(255, 255, 255, .022);
  transition: .2s;
  min-height: 236px;
}
.job-card:hover { border-color: rgba(163, 196, 214, .25); background: rgba(255, 255, 255, .04); }
.job-card.is-active { border-color: var(--job-color, var(--accent)); box-shadow: 0 0 0 1px rgba(67, 232, 208, .1), 0 12px 35px rgba(0, 0, 0, .25); }
.job-card.is-locked { opacity: .42; }
.job-card.is-complete::before {
  content: 'COMPLETE'; position: absolute; top: 12px; right: 12px;
  font-size: 7px; font-weight: 800; letter-spacing: .12em; color: var(--green);
  border: 1px solid rgba(98, 208, 164, .3); border-radius: 3px; padding: 2px 4px;
}
.job-tag { font-size: 8px; font-weight: 800; letter-spacing: .18em; color: var(--job-color, var(--accent)); }
.job-card h3 { margin: 8px 0 4px; font-family: var(--font-display); font-size: 16px; font-weight: 700; line-height: 1.15; }
.job-client { color: var(--dim); font-size: 9.5px; letter-spacing: .04em; }
.job-blurb { margin: 9px 0 10px; color: var(--muted); font-size: 10.5px; line-height: 1.35; min-height: 41px; }
.job-targets { display: flex; gap: 6px; margin-bottom: 8px; }
.job-target { flex: 1; padding: 6px 7px; border-radius: 5px; background: rgba(255, 255, 255, .04); border: 1px solid rgba(255, 255, 255, .05); }
.job-target span { display: block; font-size: 6.5px; letter-spacing: .13em; color: var(--dim); font-weight: 700; }
.job-target b { font-family: var(--font-display); font-size: 15px; font-weight: 700; }
.job-foot { display: flex; align-items: center; justify-content: space-between; margin-top: auto; padding-top: 9px; border-top: 1px solid rgba(255, 255, 255, .07); }
.job-reward { font-size: 8px; color: var(--dim); letter-spacing: .1em; font-weight: 700; }
.job-reward b { display: block; margin-top: 2px; font-family: var(--font-display); font-size: 14px; color: var(--gold); }
.job-stars { color: var(--gold); letter-spacing: 2px; font-size: 13px; }
.job-pick {
  margin-top: 9px; width: 100%;
  border: 1px solid rgba(255, 255, 255, .12);
  background: rgba(255, 255, 255, .045);
  color: var(--text);
  border-radius: 5px;
  padding: 6px;
  font-size: 8px; font-weight: 800; letter-spacing: .14em;
}
.job-pick:hover { background: rgba(255, 255, 255, .09); }
.job-card.is-active .job-pick { background: var(--accent); color: #05201d; border-color: var(--accent); }
.job-card.is-locked .job-pick { pointer-events: none; }
.free-card { grid-column: span 1; border-style: dashed; }
.contract-note { display: flex; align-items: center; gap: 8px; margin-top: 16px; padding: 9px 11px; border-radius: 6px; border: 1px solid rgba(97, 184, 255, .16); background: rgba(97, 184, 255, .045); color: var(--muted); font-size: 10px; }
.contract-note b { color: var(--blue); }

/* results */
.results-modal { width: min(980px, 94vw); padding: 0; overflow: hidden; }
.results-banner { position: relative; padding: 22px 26px 16px; border-bottom: 1px solid rgba(255, 255, 255, .07); overflow: hidden; }
.results-banner::after { content: ''; position: absolute; right: -40px; top: -90px; width: 300px; height: 300px; border-radius: 50%; background: radial-gradient(circle, var(--result-glow, rgba(67,232,208,.18)), transparent 68%); pointer-events: none; }
.results-title { display: flex; align-items: flex-end; justify-content: space-between; gap: 20px; }
.results-title h2 { margin: 8px 0 0; font-family: var(--font-display); font-size: clamp(30px, 4.6vw, 52px); line-height: .95; font-weight: 800; letter-spacing: .01em; }
.results-title h2.fail { color: var(--red); }
.results-stars { font-size: 27px; letter-spacing: 6px; color: var(--gold); text-shadow: 0 0 24px rgba(255, 209, 102, .3); min-height: 35px; }
.results-stars .dim { color: rgba(255, 255, 255, .14); text-shadow: none; }
.results-banner p { margin: 8px 0 0; color: var(--muted); font-size: 12px; }
.results-body { padding: 18px 26px 22px; display: grid; grid-template-columns: 1.2fr .9fr; gap: 22px; }
.results-chart-wrap { min-width: 0; }
.results-chart-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px; }
.results-chart-head .panel-kicker { color: var(--dim); }
#resultsChart { display: block; width: 100%; height: 228px; }
.results-metrics { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.result-metric { padding: 9px 10px; border-radius: 7px; background: rgba(255, 255, 255, .028); border: 1px solid rgba(255, 255, 255, .06); }
.result-metric span { display: block; font-size: 7px; letter-spacing: .16em; color: var(--dim); font-weight: 700; }
.result-metric b { display: inline-block; margin-top: 3px; font-family: var(--font-display); font-size: 18px; font-weight: 700; }
.result-metric em { font-style: normal; margin-left: 3px; font-size: 7px; color: var(--dim); font-weight: 700; }
.result-metric.big b { font-size: 26px; color: var(--accent); }
.result-metric.big.tq b { color: var(--blue); }
.result-metric.warn b { color: var(--red); }
.constraint-report { margin-top: 12px; display: flex; flex-direction: column; gap: 5px; }
.report-line { display: flex; align-items: center; gap: 7px; font-size: 10px; color: var(--muted); font-weight: 600; }
.report-line i { width: 6px; height: 6px; border-radius: 50%; flex: none; }
.report-line.pass i { background: var(--green); box-shadow: 0 0 6px var(--green); }
.report-line.fail i { background: var(--red); box-shadow: 0 0 6px var(--red); }
.report-line.fail { color: #ffb3ba; }
.report-line b { margin-left: auto; color: var(--text); }
.coach {
  grid-column: 1 / -1;
  display: flex; gap: 10px; align-items: flex-start;
  padding: 10px 12px;
  border-radius: 8px;
  background: rgba(255, 209, 102, .045);
  border: 1px solid rgba(255, 209, 102, .14);
}
.coach b { color: var(--gold); font-size: 8px; letter-spacing: .14em; flex: none; padding-top: 2px; }
.coach p { margin: 0; color: #c8bd9d; font-size: 10.5px; line-height: 1.4; }
.results-foot { display: flex; align-items: center; justify-content: space-between; gap: 14px; padding: 16px 26px 20px; border-top: 1px solid rgba(255, 255, 255, .07); background: rgba(0, 0, 0, .16); }
.payout { display: flex; flex-direction: column; }
.payout span { font-size: 8px; letter-spacing: .18em; color: var(--dim); font-weight: 700; }
.payout b { margin-top: 2px; font-family: var(--font-display); font-size: 26px; color: var(--gold); }
.payout small { color: var(--dim); font-size: 9px; }
.results-actions { display: flex; gap: 8px; }
.btn {
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, .035);
  color: var(--muted);
  padding: 10px 16px;
  border-radius: 5px;
  font-size: 9px; font-weight: 800; letter-spacing: .14em;
  transition: .16s;
}
.btn:hover { color: var(--text); border-color: var(--line-strong); background: rgba(255, 255, 255, .07); }
.btn.primary { background: var(--accent); border-color: var(--accent); color: #04201d; }
.btn.primary:hover { filter: brightness(1.08); background: var(--accent); color: #04201d; }
.btn.orange { background: var(--orange); border-color: var(--orange); color: #220d03; }

/* help */
.help-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.help-block { padding: 13px 14px; border-radius: 8px; border: 1px solid rgba(255, 255, 255, .07); background: rgba(255, 255, 255, .025); }
.help-block h3 { margin: 0 0 6px; font-size: 10px; letter-spacing: .16em; color: var(--accent); font-family: var(--font-display); }
.help-block p { margin: 0; color: var(--muted); font-size: 11px; line-height: 1.45; }
.help-block p + p { margin-top: 6px; }
.help-block b { color: var(--text); }
.help-keys { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
.help-keys span { border: 1px solid var(--line); border-radius: 4px; padding: 3px 6px; font-size: 8px; color: var(--muted); font-weight: 600; }
.help-keys kbd { background: rgba(255,255,255,.08); border-radius: 3px; padding: 1px 4px; font-family: var(--font-body); color: var(--text); }

/* ============================== misc ============================== */
@keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: .35; } }
@keyframes knockFlash { from { box-shadow: 0 0 0 rgba(255, 77, 94, 0); } to { box-shadow: 0 0 18px rgba(255, 77, 94, .45); } }
@keyframes sheen { 0%, 62% { left: -40%; } 88%, 100% { left: 130%; } }
@keyframes livePulse { 0%, 100% { box-shadow: 0 0 0 1px rgba(255, 77, 94, .4), 0 0 28px rgba(255, 77, 94, .16); } 50% { box-shadow: 0 0 0 2px rgba(255, 77, 94, .8), 0 0 40px rgba(255, 77, 94, .4); } }
@keyframes startPulse { 0%, 100% { box-shadow: 0 0 40px rgba(67, 232, 208, .18); } 50% { box-shadow: 0 0 60px rgba(67, 232, 208, .32); } }
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes modalIn { from { opacity: 0; transform: translateY(16px) scale(.985); } to { opacity: 1; transform: none; } }

#rotateHint {
  position: absolute; left: 50%; top: 50%; z-index: 70;
  transform: translate(-50%, -50%);
  padding: 8px 13px; border-radius: 5px;
  background: rgba(4, 8, 11, .8); border: 1px solid var(--line);
  color: var(--muted); font-size: 9px; letter-spacing: .2em; font-weight: 700;
  pointer-events: none; transition: opacity .4s;
}
#rotateHint.hidden { display: none; }

#fatal { position: absolute; inset: 0; z-index: 200; display: grid; place-items: center; background: #05080b; padding: 30px; }
#fatal > div { max-width: 480px; text-align: center; }
#fatal h2 { font-family: var(--font-display); color: var(--red); letter-spacing: .1em; }
#fatal p { color: var(--muted); font-size: 14px; line-height: 1.5; }

/* ============================== responsive ============================== */
@media (max-width: 1180px) {
  #hud { grid-template-columns: 250px minmax(0, 1fr) 332px; gap: 12px; padding: 12px 14px 14px; }
  .chart-panel { width: min(470px, 100%); }
  .chart-hint, .cam-hint { display: none; }
  .goal b { font-size: 21px; }
  .pred-main b { font-size: 19px; }
}

@media (max-width: 980px) {
  :root { --topbar-h: 60px; }
  #mainNav .nav-btn { padding: 7px 10px; font-size: 10px; }
  #mainNav .nav-btn[data-action="garage"] { display: none; }
  .top-stats { gap: 10px; }
  .stat-rep { display: none; }
  #hud { grid-template-columns: 228px minmax(0, 1fr) 318px; gap: 10px; padding: 10px 12px 12px; }
  .brand-type small { display: none; }
  .chart-foot { font-size: 7px; gap: 7px; }
  .contract-card { padding: 12px; }
  .gauge svg { width: 66px; height: 66px; }
  .g-read { top: 20px; }
}

@media (max-width: 820px) {
  #hud { display: block; padding: 0; }
  #leftRail { display: none; }
  #centerStage { position: absolute; inset: 0 0 44dvh 0; }
  #rightRail {
    position: absolute;
    left: 0; right: 0; bottom: 0;
    height: 44dvh;
    padding: 0 8px calc(8px + env(safe-area-inset-bottom));
    z-index: 15;
  }
  #consolePanel { border-radius: 14px 14px 0 0; background: linear-gradient(180deg, rgba(17, 23, 30, .96), rgba(7, 10, 13, .985)); }
  .console-head { padding: 9px 13px 7px; align-items: center; }
  .console-head h2 { font-size: 12px; margin-top: 3px; }
  .console-head .panel-kicker { display: none; }
  .console-view { padding: 8px 12px 10px; }
  .chart-panel { display: none; }
  #cameraBar { top: 43px; padding: 3px; }
  .cam-btn { padding: 5px 9px; font-size: 8px; }
  .cam-hint { display: none; }
  #toast { bottom: calc(44dvh + 16px); font-size: 10px; }
  #pullHud { bottom: 18px; width: calc(100% - 20px); }
  body.pulling #centerStage { inset: 0 0 0 0; }
  body.pulling #rightRail { transform: translateY(112%); opacity: 0; pointer-events: none; transition: .3s; }
  body.pulling #cameraBar { opacity: 0; }
  body.pulling #mobileTelemetry { top: 56px; }
  .spec-strip { margin-bottom: 8px; padding: 6px 8px; }
  .sliders { gap: 6px; }
  .slider-top label { font-size: 8px; }
  .slider-val b { font-size: 13px; }
  .slider-scale { display: none; }
  .fuel-block { margin-top: 7px; padding-top: 7px; }
  .prediction { margin-top: 7px; padding: 7px 9px; }
  .pred-main b { font-size: 18px; }
  .pred-flags { margin-top: 5px; }
  .pred-warning { font-size: 8px; margin-top: 4px; }
  .run-btn { margin-top: 8px; padding: 10px 13px 8px; position: sticky; bottom: 0; z-index: 2; }
  .run-btn .run-main { font-size: 13px; }
  .tune-hint { display: none; }
  #mobileTelemetry {
    display: flex;
    position: absolute;
    top: 6px; left: 12px; right: 12px;
    z-index: 5;
    justify-content: center;
    gap: 8px;
    pointer-events: none;
  }
  #mobileTelemetry > div {
    min-width: 61px;
    padding: 5px 8px;
    border-radius: 5px;
    background: rgba(5, 9, 12, .62);
    border: 1px solid rgba(160, 190, 205, .12);
    backdrop-filter: blur(9px);
    text-align: center;
  }
  #mobileTelemetry span { display: block; font-size: 6px; letter-spacing: .16em; color: var(--dim); font-weight: 700; }
  #mobileTelemetry b { display: block; margin-top: 2px; font-family: var(--font-display); font-size: 12px; font-weight: 700; }
  #mobileTelemetry #mKnock b { color: var(--green); }
  #mobileTelemetry #mKnock.bad b { color: var(--red); }
  #mobileTelemetry #mKnock.warn b { color: var(--gold); }
  .modal { padding: 18px; width: 96vw; max-height: 92dvh; }
  .contract-grid { grid-template-columns: 1fr 1fr; }
  .results-body { grid-template-columns: 1fr; }
  #resultsChart { height: 190px; }
  .help-grid { grid-template-columns: 1fr; }
  .title-inner { padding-left: 7vw; }
}

@media (max-width: 600px) {
  :root { --topbar-h: 54px; }
  #topbar { padding-left: 12px; padding-right: 12px; gap: 8px; }
  .brand-mark { width: 25px; height: 25px; }
  .brand-type strong { font-size: 15px; }
  .brand-type small { display: none; }
  #mainNav { padding: 2px; gap: 0; }
  #mainNav .nav-btn { padding: 7px 8px; font-size: 9px; letter-spacing: .1em; }
  #mainNav .nav-btn.nav-help { width: 26px; padding: 7px 0; }
  .top-stats { gap: 7px; }
  .stat span { font-size: 6px; }
  .stat b { font-size: 12px; }
  .icon-btn { width: 29px; height: 29px; }
  .icon-btn svg { width: 16px; height: 16px; }
  #centerStage { inset: 0 0 47dvh 0; }
  #rightRail { height: 47dvh; }
  #toast { bottom: calc(47dvh + 12px); }
  .title-inner { width: 90vw; padding: 0 0 0 6vw; }
  .title-inner h1 { font-size: 21vw; margin: 20px 0 12px; }
  .title-copy { font-size: 12.5px; max-width: 92%; }
  .title-tagline { font-size: 11px; letter-spacing: .1em; }
  .title-chips { gap: 5px; margin-top: 16px; }
  .title-chips span { font-size: 7px; padding: 4px 6px; }
  .start-btn { margin-top: 24px; min-width: 200px; padding: 14px 22px; font-size: 13px; }
  .title-foot { gap: 10px; font-size: 6.5px; margin-top: 24px; }
  .title-version { display: none; }
  .title-corner { width: 18px; height: 18px; }
  #cameraBar { top: 47px; }
  #mobileTelemetry { left: 6px; right: 6px; gap: 4px; }
  #mobileTelemetry > div { min-width: 0; flex: 1; padding: 4px 3px; }
  #mobileTelemetry b { font-size: 10px; }
  .console-head { padding: 7px 11px 6px; }
  .console-tab { padding: 5px 7px; }
  .spec-strip { grid-template-columns: 1.2fr .8fr .6fr; }
